import{_ as a,o as t,c as i,a2 as n}from"./chunks/framework.CDpkVv68.js";const h=JSON.parse('{"title":"Disabled regions and shield use","description":"","frontmatter":{},"headers":[],"relativePath":"game-design/combat/disability.md","filePath":"game-design/combat/disability.md"}'),s={name:"game-design/combat/disability.md"};function o(r,e,d,l,c,p){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="disabled-regions-and-shield-use" tabindex="-1">Disabled regions and shield use <a class="header-anchor" href="#disabled-regions-and-shield-use" aria-label="Permalink to &quot;Disabled regions and shield use&quot;">​</a></h1><p><strong>Design status: Accepted consequence and experimental side/failure policies. Implementation: Stage 2A live integrity/condition transitions; no shield behavior.</strong></p><p>Disabled means loss of function, not automatic amputation or an independent death condition. When the shield-supporting arm becomes Disabled, the same owned shield moves to the backpack, never the ground, and re-equip is blocked while the arm remains Disabled. Ordinary later death/loot rules still apply.</p><p>Slice 0 uses the approved experimental <code>LeftArm</code> support-arm convention. Equipment layer <code>TwoHanded</code> is not anatomical handedness. Other zero regions in this first slice cause no extra death, movement slowdown, accuracy penalty or weapon drop. A disabled RightArm must not accidentally trigger the provisional LeftArm shield rule.</p><p>The full-backpack capacity exception and exclusion of missing/deleted/custom backpacks are Accepted prototype policies; they are not permanent inventory design. Stop affected implementation if ownership cannot be preserved.</p><p>Recovery does not automatically re-equip the shield. Technical shield-stow contract specifies transitions and dangerous legacy helper behavior. <strong>Gap:</strong> Stage 2A deliberately stops at the documented intermediate accumulation stage. Disabled is observable, but shield relocation/equip restrictions and every other functional penalty are deferred. Safe relocation and all equip routes require later implementation and runtime checks.</p>',6)])])}const u=a(s,[["render",o]]);export{h as __pageData,u as default};
